1	'use client'
2	
3	import { useQuery } from '@tanstack/react-query'
4	import { Wand2, DollarSign, Star } from 'lucide-react'
5	import { KpiCard } from '@/components/shared/KpiCard'
6	import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
7	import { Badge } from '@/components/ui/badge'
8	import { Skeleton } from '@/components/ui/skeleton'
9	import { DataState } from '@/components/shared/DataState'
10	import { EmptyState } from '@/components/shared/EmptyState'
11	import { ChartSkeleton } from '@/components/skeletons'
12	import { formatCurrency } from '@/lib/utils'
13	import dynamic from 'next/dynamic'
14	
15	const RechartsBarChart = dynamic(() => import('./RechartsBarChart'), {
16	  ssr: false,
17	  loading: () => <Skeleton className="h-56 w-full" />,
18	})
19	
20	interface ModelStat {
21	  model: string
22	  count: number
23	  cost: number
24	}
25	
26	interface MonthlyPoint {
27	  month: string
28	  count: number
29	  cost: number
30	}
31	
32	interface AiUsageData {
33	  kpis: {
34	    total: number
35	    totalCost: number
36	    totalTokens: number
37	    avgRating: number | null
38	  }
39	  modelBreakdown: ModelStat[]
40	  monthlyTrend: MonthlyPoint[]
41	}
42	
43	export function AiUsageReportClient() {
44	  const { data, isLoading, error } = useQuery<AiUsageData>({
45	    queryKey: ['reports', 'ai'],
46	    queryFn: () => fetch('/api/reports/ai').then((r) => r.json()),
47	    staleTime: 5 * 60 * 1000,
48	  })
49	
50	  return (
51	    <DataState
52	      data={data}
53	      isLoading={isLoading}
54	      isError={!!error}
55	      error={error instanceof Error ? error : null}
56	      loadingSlot={<ChartSkeleton />}
57	      isEmpty={data?.kpis.total === 0}
58	      emptySlot={
59	        <EmptyState
60	          icon={Wand2}
61	          title="No AI generations yet"
62	          description="AI design generations will appear here once clients start using the feature."
63	          variant="default"
64	        />
65	      }
66	    >
67	      {(d) => {
68	        const trendForChart = d.monthlyTrend.map((p) => ({
69	          name: p.month,
70	          value: Math.round(p.cost / 100),
71	        }))
72	
73	        return (
74	          <div className="space-y-6">
75	            {/* KPIs */}
76	            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
77	              <KpiCard label="Generations" value={d.kpis.total} subtextLabel="total AI calls" icon={Wand2} index={0} />
78	              <KpiCard
79	                label="Total Cost"
80	                value={formatCurrency(d.kpis.totalCost)}
